448:         const DynamicApis &apis = DynamicApis::instance();
449:         if (apis.pGetDpiForWindow) { // Win10
450:             return apis.pGetDpiForWindow(hwnd);
451:         } else if (apis.pGetDpiForMonitor) { // Win8.1
452:             HMONITOR monitor = ::MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST);
453:             UINT dpiX{0};
454:             UINT dpiY{0};
455:             apis.pGetDpiForMonitor(monitor, MDT_EFFECTIVE_DPI, &dpiX, &dpiY);
456:             return dpiX;
457:         } else { // Win2K
458:             HDC hdc = ::GetDC(nullptr);
459:             const int dpiX = ::GetDeviceCaps(hdc, LOGPIXELSX);
460:             // const int dpiY = ::GetDeviceCaps(hdc, LOGPIXELSY);
461:             ::ReleaseDC(nullptr, hdc);
462:             return quint32(dpiX);
463:         }
464:     }
465: 
466:     inline quint32 getSystemMetricsForDpi(int index, quint32 dpi) {
467:         const DynamicApis &apis = DynamicApis::instance();
468:         if (apis.pGetSystemMetricsForDpi) {
469:             return apis.pGetSystemMetricsForDpi(index, dpi);
470:         }
471:         const int result = ::GetSystemMetrics(index);
472:         // GetSystemMetrics() always give you scaled value.
473:         if (dpi != USER_DEFAULT_SCREEN_DPI) {
474:             return result;
475:         }
476:         const qreal dpr = qreal(dpi) / qreal(USER_DEFAULT_SCREEN_DPI);
477:         // ### Not sure how Windows itself rounds non-integer value.
478:         return qFloor(qreal(result) / dpr);
479:     }
480: 
481:     inline quint32 getWindowFrameBorderThickness(HWND hwnd) {
482:         Q_ASSERT(hwnd);
483:         const DynamicApis &apis = DynamicApis::instance();
484:         if (isWin11OrGreater()) {
485:             UINT result = 0;
486:             if (SUCCEEDED(apis.pDwmGetWindowAttribute(hwnd, _DWMWA_VISIBLE_FRAME_BORDER_THICKNESS,
487:                                                       &result, sizeof(result)))) {
488:                 return result;
489:             }
490:         }
491:         if (isWin10OrGreater()) {
492:             const quint32 dpi = getDpiForWindow(hwnd);
493:             // When DPI is 96, it should be 1px.
494:             return getSystemMetricsForDpi(SM_CXBORDER, dpi);
495:         }
496:         // There's no such thing (a visible frame border line) before Win10.
497:         return 0;
498:     }
499: 
500:     inline quint32 getResizeBorderThickness(HWND hwnd) {
501:         Q_ASSERT(hwnd);
502:         const quint32 dpi = getDpiForWindow(hwnd);
503:         // When DPI is 96, SM_CXSIZEFRAME is 4px, SM_CXPADDEDBORDER is also 4px,
504:         // so the result should be 8px. This result won't be affected by OS version,
505:         // it's 8px in Win7, and so in Win11.
506:         return getSystemMetricsForDpi(SM_CXSIZEFRAME, dpi) +
507:                getSystemMetricsForDpi(SM_CXPADDEDBORDER, dpi);
508:     }
509: 
510:     inline quint32 getTitleBarHeight(HWND hwnd) {
511:         Q_ASSERT(hwnd);
512:         const quint32 dpi = getDpiForWindow(hwnd);
513:         // When DPI is 96, SM_CYCAPTION is 23px, so the result should be 31px.
514:         // However, according to latest MS design manual, the title bar height
515:         // should be 32px, maybe there's some rounding issue.
516:         return getSystemMetricsForDpi(SM_CYCAPTION, dpi) +
517:                getSystemMetricsForDpi(SM_CYSIZEFRAME, dpi) +
518:                getSystemMetricsForDpi(SM_CXPADDEDBORDER, dpi);
519:     }
520: 
521: }
